/**
 * Expo config plugin: sign release builds with a FIXED keystore.
 *
 * Why this exists
 * ---------------
 * The Expo template signs release builds with `android/app/debug.keystore`.
 * That file is GENERATED, and `android/` is regenerated by `expo prebuild`, so
 * the signing key changes:
 *
 *   - every time the native project is regenerated, and
 *   - on every machine that builds it.
 *
 * Android identifies an app by package name AND signing certificate, and it
 * refuses to install a build whose certificate differs from the one already
 * installed. The error it shows is just "App not installed", with no indication
 * that signing is the cause. That is why handing a new APK round the team
 * failed for anyone who still had an older one on their phone: the only fix
 * available to them was to uninstall first, which nobody knows to do.
 *
 * A fixed keystore, checked in and pointed at from outside the generated tree,
 * makes every build from every machine mutually installable. Upgrades then work
 * the way they should: install over the top, keep your data.
 *
 * SECURITY, stated plainly
 * ------------------------
 * This keystore and its password are IN THE REPOSITORY. Anyone who can read the
 * repo can sign an APK that Android will accept as an update to this one. That
 * is an acceptable trade for a demo app distributed by hand, and it is NOT
 * acceptable for anything published to a store or installed by people outside
 * the team. Before any real distribution: generate a new keystore, keep it out
 * of version control, and inject the credentials from the environment.
 *
 * `android/` is generated, so without this plugin `expo prebuild --clean` puts
 * the debug keystore back and the problem returns. Verify after a prebuild:
 *   grep -A3 'signingConfigs' android/app/build.gradle   # -> release {...}
 */
const path = require('path');

const { withAppBuildGradle } = require('@expo/config-plugins');

const KEYSTORE = 'matrix-release.keystore';
const ALIAS = 'matrix';
// Not a secret in any meaningful sense — see the note above. Named constants so
// there is exactly one place to change when this is done properly.
const STORE_PASSWORD = 'matrixdemo';
const KEY_PASSWORD = 'matrixdemo';

/**
 * Resolved against `rootProject`, which is `android/` — so one level up is
 * `mobile/`, where the keystore lives outside the generated tree.
 *
 * It has to be `rootProject.file`, not bare `file`. Inside `app/build.gradle`,
 * `file()` resolves against the APP MODULE directory (`android/app/`), so
 * `'../keystores/…'` silently pointed at `android/keystores/…`, and the build
 * ran for sixteen minutes before failing at `validateSigningRelease`.
 */
const RELATIVE = path.posix.join('..', 'keystores', KEYSTORE);

const SIGNING_CONFIG = `        release {
            storeFile rootProject.file('${RELATIVE}')
            storePassword '${STORE_PASSWORD}'
            keyAlias '${ALIAS}'
            keyPassword '${KEY_PASSWORD}'
        }
`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error(
        'with-release-signing: app/build.gradle is not Groovy. The Expo template ' +
          'changed; update this plugin rather than letting release builds fall ' +
          'back to the debug keystore.',
      );
    }

    let src = cfg.modResults.contents;

    // Idempotent: a second prebuild must not append a second config block.
    if (!src.includes('keyAlias \'' + ALIAS + '\'')) {
      const anchor = /(signingConfigs\s*\{\s*\n)/;
      if (!anchor.test(src)) {
        throw new Error(
          'with-release-signing: no signingConfigs block found in app/build.gradle.',
        );
      }
      src = src.replace(anchor, `$1${SIGNING_CONFIG}`);
    }

    // Point the release build type at it. The template line names the DEBUG
    // config inside the release block, which is the whole bug.
    const before = src;
    src = src.replace(
      /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?signingConfig\s+)signingConfigs\.debug/,
      '$1signingConfigs.release',
    );
    if (src === before && !src.includes('signingConfigs.release')) {
      throw new Error(
        'with-release-signing: could not repoint the release build type. Refusing ' +
          'to produce a debug-signed release APK silently.',
      );
    }

    cfg.modResults.contents = src;
    return cfg;
  });
};
